def normalize_redirect_uri(uri):
    """Normalize redirect URI for comparison.
    Handles mobile deep links and HTTPS URLs uniformly."""
    parsed = urlparse(uri)
    # Reconstruct without fragment, normalize path
    scheme = parsed.scheme.lower()
    host = parsed.hostname.lower() if parsed.hostname else ""
    port = parsed.port
    path = parsed.path.rstrip("/") if parsed.path else ""

    if port and port not in (80, 443):
        normalized = f"{scheme}://{host}:{port}{path}"
    else:
        normalized = f"{scheme}://{host}{path}"

    return normalized

def validate_redirect_uri(client_id, redirect_uri):
    """Validate redirect_uri against registered URIs for the client.
    Uses exact normalized comparison to prevent bypass."""
    if client_id not in REGISTERED_CLIENTS:
        return False

    client = REGISTERED_CLIENTS[client_id]
    normalized_input = normalize_redirect_uri(redirect_uri)

    for allowed in client["allowed_redirects"]:
        normalized_allowed = normalize_redirect_uri(allowed)
        if normalized_input == normalized_allowed:
            return True

    return False

def generate_auth_code(client_id, user_id, redirect_uri, chain_challenge=None):
    """Generate a short-lived authorization code bound to the redirect URI."""
    code = secrets.token_urlsafe(32)
    ISSUED_CODES[code] = {
        "client_id": client_id,
        "user_id": user_id,
        "redirect_uri": redirect_uri,
        "chain_challenge": chain_challenge,
        "issued_at": time.time(),
        "used": False
    }
    return code

@app.route("/oauth/authorize", methods=["GET"])
def authorize():
    """OAuth 2.0 authorization endpoint with Solidity contract binding."""
    client_id = request.args.get("client_id")
    redirect_uri = request.args.get("redirect_uri")
    response_type = request.args.get("response_type")
    state = request.args.get("state")
    chain_sig = request.args.get("chain_sig")  # Optional on-chain auth

    if not client_id or not redirect_uri or not response_type:
        return jsonify({"error": "invalid_request"}), 400

    if response_type != "code":
        return jsonify({"error": "unsupported_response_type"}), 400

    if client_id not in REGISTERED_CLIENTS:
        return jsonify({"error": "invalid_client"}), 401

    if not validate_redirect_uri(client_id, redirect_uri):
        return jsonify({"error": "invalid_redirect_uri"}), 400

    # If client has a Solidity contract, verify chain signature
    client = REGISTERED_CLIENTS[client_id]
    chain_challenge = None
    if client["solidity_contract"] and chain_sig:
        if not verify_solidity_signature(
            f"authorize:{client_id}:{state}",
            chain_sig,
            client["solidity_contract"]
        ):
            return jsonify({"error": "invalid_chain_signature"}), 403
        chain_challenge = hashlib.sha256(
            f"{chain_sig}:{time.time()}".encode()
        ).hexdigest()

    # Simulate authenticated user (in production, check session)
    user_id = session.get("user_id", "user_demo_123")

    code = generate_auth_code(client_id, user_id, redirect_uri, chain_challenge)

    # Build redirect with code. URL-encode parameters to prevent
    # parameter injection/pollution via attacker-controlled 'state'.
    params = {"code": code}
    if state:
        params["state"] = state
    separator = "&" if "?" in redirect_uri else "?"
    callback_url = f"{redirect_uri}{separator}{urlencode(params)}"

    return redirect(callback_url)

@app.route("/oauth/token", methods=["POST"])
def token():
    """Token exchange endpoint - exchanges auth code for access token."""
    grant_type = request.form.get("grant_type")
    code = request.form.get("code")
    redirect_uri = request.form.get("redirect_uri")
    client_id = request.form.get("client_id")
    client_secret = request.form.get("client_secret")

    if grant_type != "authorization_code":
        return jsonify({"error": "unsupported_grant_type"}), 400

    if not code or code not in ISSUED_CODES:
        return jsonify({"error": "invalid_grant"}), 400

    code_data = ISSUED_CODES[code]

    # Verify code hasn't expired (5 minute window)
    if time.time() - code_data["issued_at"] > 300:
        del ISSUED_CODES[code]
        return jsonify({"error": "expired_grant"}), 400

    # Verify code hasn't been used
    if code_data["used"]:
        return jsonify({"error": "invalid_grant"}), 400

    # Verify client credentials
    if client_id != code_data["client_id"]:
        return jsonify({"error": "invalid_client"}), 401

    if client_id not in REGISTERED_CLIENTS:
        return jsonify({"error": "invalid_client"}), 401

    expected_secret = REGISTERED_CLIENTS[client_id]["client_secret"]
    if not hmac.compare_digest(client_secret or "", expected_secret):
        return jsonify({"error": "invalid_client"}), 401

    # Verify redirect_uri matches what was used in authorization
    if normalize_redirect_uri(redirect_uri or "") != normalize_redirect_uri(code_data["redirect_uri"]):
        return jsonify({"error": "invalid_grant"}), 400

    # Mark code as used
    code_data["used"] = True

    # Generate tokens
    access_token = secrets.token_urlsafe(48)
    refresh_token = secrets.token_urlsafe(48)

    return jsonify({
        "access_token": access_token,
        "token_type": "Bearer",
        "expires_in": 3600,
        "refresh_token": refresh_token,
        "chain_challenge": code_data.get("chain_challenge")
    })

